using UnityEngine;
using UnityEditor;
using UnityEditor.TestTools.TestRunner.Api;
internal class JointSamplingTestCallbacks : ICallbacks
{
    public void RunStarted(ITestAdaptor tests) {}
    public void TestStarted(ITestAdaptor test) {}
    public void TestFinished(ITestResultAdaptor result) {}
    public void RunFinished(ITestResultAdaptor result)
    {
        TestRunnerApi.SaveResultToFile(result, "E:/VividRP_Reborn/Packages/VividRP/Temp~/bnd-joint/joint-index-tests.xml");
    }
}
internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        if (Application.dataPath != "E:/VividRP_Reborn/Assets" || EditorApplication.isPlaying) return;
        var api = ScriptableObject.CreateInstance<TestRunnerApi>();
        var callback = new JointSamplingTestCallbacks();
        TestRunnerApi.RegisterTestCallback(callback);
        try
        {
            var filter = new Filter { testMode = TestMode.EditMode,
                groupNames = new[] { "^VividRP.Editor.Tests.VirtualShadowMapReceiverQualityTests.SMRTJoint_" } };
            string run = api.Execute(new ExecutionSettings(filter) { runSynchronously = true });
            result.Log("Completed synchronous joint-index tests: " + run);
        }
        finally { TestRunnerApi.UnregisterTestCallback(callback); Object.DestroyImmediate(api); }
    }
}
